(()=>{
'use strict';const atlas=window.YUGEN_ATLAS;if(!atlas)return;const entries=atlas.entries,categories=atlas.categories;const byId=new Map(entries.map(e=>[e.id,e]));const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const href=e=>categories[e.category].page+'?ler='+encodeURIComponent(e.id);const query=(s,root=document)=>root.querySelector(s);const all=(s,root=document)=>[...root.querySelectorAll(s)];let photoCredits=[];
fetch('photo-credits.json').then(r=>r.ok?r.json():[]).then(data=>{photoCredits=data}).catch(()=>{});
function saved(){try{const x=JSON.parse(localStorage.getItem('yugen-saved-v1')||'[]');return Array.isArray(x)?[...new Set(x.filter(id=>byId.has(id)))]:[]}catch{return []}}
function wish(){try{return localStorage.getItem('yugen-wish-v1')||''}catch{return ''}}
function syncLocks(){document.body.classList.toggle('body-modal-lock',!!query('dialog[open]'))}
const toast=document.createElement('div');toast.className='magazine-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.append(toast);let toastTimer;function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}
function updateSavedUI(){const set=new Set(saved());all('[data-save]').forEach(b=>{const e=byId.get(b.dataset.save);if(!e)return;const on=set.has(e.id);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',(on?'Retirar do caderno: ':'Guardar no caderno: ')+e.title);if(b.classList.contains('entry-save'))b.textContent=on?'✓':'＋';else b.textContent=on?'✓ Guardado no caderno':'＋ Guardar no caderno'});all('[data-saved-count]').forEach(el=>el.textContent=String(set.size));const exportButton=query('#export-notebook');if(exportButton)exportButton.disabled=set.size===0&&!wish()}
function toggleSave(id){const e=byId.get(id);if(!e)return;let ids=saved();const had=ids.includes(id);ids=had?ids.filter(x=>x!==id):[...ids,id];try{localStorage.setItem('yugen-saved-v1',JSON.stringify(ids))}catch{notify('Este navegador não permitiu guardar a descoberta.');return}updateSavedUI();renderNotebook();notify(had?'Descoberta retirada do caderno.':'Descoberta guardada no seu caderno.');}
// Global atlas: keyboard-accessible search and entry links.
const atlasDialog=document.createElement('dialog');atlasDialog.className='atlas-dialog';atlasDialog.id='atlas-dialog';atlasDialog.setAttribute('aria-labelledby','atlas-dialog-title');atlasDialog.innerHTML='<button class="close-dialog" aria-label="Fechar atlas">✕</button><p class="eyebrow">52 DESCOBERTAS / SETE JEITOS DE OLHAR</p><h2 id="atlas-dialog-title">O que desperta<br><em>sua curiosidade?</em></h2><label class="atlas-search-line"><span aria-hidden="true">⌕</span><input type="search" id="atlas-search" placeholder="Uma cidade, pessoa, obra ou costume…" aria-label="Buscar em todo o Yūgen" autocomplete="off"></label><div class="atlas-chips" aria-label="Filtrar busca por tema"><button data-atlas-filter="all" class="active" aria-pressed="true">Tudo</button>'+Object.entries(categories).map(([id,c])=>'<button data-atlas-filter="'+id+'" aria-pressed="false">'+esc(c.name)+'</button>').join('')+'</div><p class="atlas-result-meta" id="atlas-result-meta" role="status"></p><div class="atlas-results" id="atlas-results"></div><div class="atlas-links"><a href="caderno.html">Meu caderno <span data-saved-count>0</span> ↗</a><a href="creditos.html">Fotografias & fontes ↗</a></div>';document.body.append(atlasDialog);let atlasFilter='all',atlasReturn;
function searchAtlas(){const term=norm(query('#atlas-search').value).trim();const found=entries.filter(e=>(atlasFilter==='all'||e.category===atlasFilter)&&norm([e.title,e.kana,e.tag,e.creator,e.lead,...e.body].join(' ')).includes(term));query('#atlas-result-meta').textContent=found.length+(found.length===1?' descoberta encontrada':' descobertas encontradas');query('#atlas-results').innerHTML=found.length?found.slice(0,30).map(e=>'<a class="atlas-result" href="'+href(e)+'"><span aria-hidden="true">'+categories[e.category].glyph+'</span><div><small>'+esc(categories[e.category].name.toUpperCase())+'</small><strong>'+esc(e.title)+'</strong></div><span aria-hidden="true">↗</span></a>').join(''):'<p class="atlas-empty">Nenhuma descoberta com esse termo. Tente um título, cidade ou outro tema.</p>';}
function openAtlas(){if(query('dialog[open]'))return;atlasReturn=document.activeElement;const menu=query('#menu-toggle');if(menu){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu')}atlasDialog.showModal();syncLocks();query('#atlas-search').focus();searchAtlas()}
query('.close-dialog',atlasDialog).addEventListener('click',()=>atlasDialog.close());atlasDialog.addEventListener('close',()=>{syncLocks();if(!query('dialog[open]'))atlasReturn?.focus()});query('#atlas-search').addEventListener('input',searchAtlas);all('[data-atlas-filter]').forEach(b=>b.addEventListener('click',()=>{atlasFilter=b.dataset.atlasFilter;all('[data-atlas-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});searchAtlas()}));
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(atlasDialog.open)atlasDialog.close();else openAtlas()}});
// A shared reader gives every discovery context, provenance and a path onward.
const reader=document.createElement('dialog');reader.className='reader-dialog';reader.id='atlas-reader';reader.setAttribute('aria-labelledby','reader-title');reader.innerHTML='<button class="close-dialog" aria-label="Fechar descoberta">✕</button><div id="reader-content"></div>';document.body.append(reader);let readerReturn,currentEntry,readerUpdating=false;
function photoLine(imageId){const c=photoCredits.find(p=>p.id===imageId);if(!c)return '<a class="reader-image-credit" href="creditos.html#'+imageId+'">Imagem, autoria, licença e data ↗</a>';return '<a class="reader-image-credit" href="creditos.html#'+imageId+'">'+(imageId==='great-wave'?'Gravura':'Foto real')+' · '+esc(c.author.trim())+' · '+esc(c.license)+' · Créditos e data ↗</a>'}
function openReader(id){const e=byId.get(id);if(!e)return;if(query('dialog[open]')&&!reader.open)return;currentEntry=e;if(!reader.open)readerReturn=document.activeElement;const image=e.image?'<img class="reader-image" src="assets/'+e.image+'.webp" alt="'+esc(e.imageAlt||e.title)+'">'+photoLine(e.image):'';query('#reader-content').innerHTML=image+'<div class="reader-inner"><p class="reader-label">'+esc(categories[e.category].name.toUpperCase())+' / '+esc(e.tag)+'</p><span class="reader-kana" aria-hidden="true">'+esc(e.kana)+'</span><h2 id="reader-title">'+esc(e.title)+'</h2><p class="reader-lead">'+esc(e.lead)+'</p>'+(e.creator?'<p class="reader-author">Autoria / criação: '+esc(e.creator)+'</p>':'')+e.body.map(p=>'<p>'+esc(p)+'</p>').join('')+(e.note?'<p class="reader-note">'+esc(e.note)+'</p>':'')+(e.start?'<p class="reader-note"><b>Por onde começar</b><br>'+esc(e.start)+'</p>':'')+'<div class="reader-actions"><button data-save="'+e.id+'" aria-pressed="false">＋ Guardar no caderno</button><button class="reader-share" id="reader-share">Copiar link ↗</button></div><div class="reader-feedback" role="status" id="reader-feedback"></div><div class="reader-source"><p>FONTES PARA CONTINUAR A LEITURA</p>'+e.sources.map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.label)+' ↗</a>').join('')+'</div>'+((e.related||[]).some(id=>byId.has(id))?'<div class="reader-related"><p>UMA DESCOBERTA PUXA OUTRA</p>'+e.related.filter(id=>byId.has(id)).map(id=>'<button data-entry="'+id+'">'+esc(byId.get(id).title)+' ↗</button>').join('')+'</div>':'')+'</div>';if(!reader.open)reader.showModal();reader.scrollTop=0;syncLocks();updateSavedUI();const url=new URL(location.href);url.searchParams.set('ler',id);history.replaceState(null,'',url.pathname+url.search+url.hash);query('#reader-share').addEventListener('click',async()=>{const url=new URL(href(e),location.href).href;try{await navigator.clipboard.writeText(url);query('#reader-feedback').textContent='Link copiado. Compartilhe esta descoberta.'}catch{query('#reader-feedback').textContent='Copie este endereço: '+url}})}
query('.close-dialog',reader).addEventListener('click',()=>reader.close());reader.addEventListener('close',()=>{syncLocks();const url=new URL(location.href);url.searchParams.delete('ler');history.replaceState(null,'',url.pathname+url.search+url.hash);readerReturn?.focus()});
function closeOnBackdrop(dialog){dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()})}closeOnBackdrop(reader);closeOnBackdrop(atlasDialog);
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){e.preventDefault();toggleSave(save.dataset.save);return}const open=e.target.closest('[data-entry]');if(open){openReader(open.dataset.entry);return}if(e.target.closest('[data-open-atlas]'))openAtlas();if(e.target.closest('[data-surprise]'))openReader(entries[Math.floor(Math.random()*entries.length)].id)});
// New pages share the same responsive menu; older chapters retain their handler.
if(!query('script[src="app.js"],script[src="chapter.js"]')){const menu=query('#menu-toggle');function closeMenu(){menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Abrir menu')}menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));menu.setAttribute('aria-label',expanded?'Fechar menu':'Abrir menu')});all('#main-nav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}})}
// Curated paths connect subjects instead of presenting isolated tiles.
const paths={images:['hokusai','edo','tezuka','astroboy'],everyday:['casa','trem','ramen','kyoto'],voices:['murasaki','ainu','naha','sakamoto']};function renderPath(key){const target=query('#path-trail');if(!target)return;target.innerHTML=paths[key].map((id,i)=>{const e=byId.get(id);return '<button class="path-stop" data-entry="'+id+'"><small>0'+(i+1)+' / '+esc(categories[e.category].name.toUpperCase())+'</small><span aria-hidden="true">'+categories[e.category].glyph+'</span><h3>'+esc(e.title)+'</h3><p>'+esc(e.lead)+'</p></button>'}).join('')};all('[data-path]').forEach(b=>b.addEventListener('click',()=>{all('[data-path]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderPath(b.dataset.path)}));renderPath('images');
// Timeline tabs work by pointer and keyboard, including in a horizontal mobile layout.
const eras=all('[data-era]');const eraMedia=matchMedia('(max-width:650px)');function orientEras(){const list=query('.era-tabs');if(list)list.setAttribute('aria-orientation',eraMedia.matches?'horizontal':'vertical')}orientEras();eraMedia.addEventListener('change',orientEras);function setEra(id){const e=byId.get(id);const stage=query('#era-stage');if(!stage||!e)return;eras.forEach(b=>{const on=b.dataset.era===id;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});stage.setAttribute('aria-labelledby','era-tab-'+id);stage.innerHTML='<div class="era-stage-inner"><span class="era-year">'+esc(e.year)+'</span><h3>'+esc(e.title)+'</h3>'+e.body.map(p=>'<p>'+esc(p)+'</p>').join('')+'<div class="stage-actions"><button class="button solid" data-entry="'+id+'">Fontes & conexões ↗</button><button class="stage-save" data-save="'+id+'">＋ Guardar no caderno</button></div></div>';updateSavedUI()}
function keyboardTabs(tabs,key,set){tabs.forEach((b,i)=>{b.addEventListener('click',()=>set(b.dataset[key]));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:tabs.length-1))%tabs.length;tabs[n].focus();set(tabs[n].dataset[key])})})}keyboardTabs(eras,'era',setEra);setEra('jomon');
// Customs are contextual scenes, not judgments about an entire population.
function setCustom(id){const e=byId.get(id),target=query('#custom-stage');if(!target||!e)return;all('[data-custom]').forEach(b=>{const on=b.dataset.custom===id;b.setAttribute('aria-pressed',String(on));b.classList.toggle('active',on)});target.innerHTML='<div class="custom-stage-inner"><div class="custom-story"><span aria-hidden="true">'+e.kana+'</span><h3>'+esc(e.title)+'</h3>'+e.body.map(t=>'<p>'+esc(t)+'</p>').join('')+'<div class="stage-actions"><button class="button solid" data-entry="'+id+'">Abra o contexto ↗</button><button class="stage-save" data-save="'+id+'">＋ Guardar no caderno</button></div></div><div class="custom-tips"><div class="custom-tip"><span>UM BOM COMEÇO</span><p>'+esc(e.do)+'</p></div><div class="custom-tip"><span>UM CUIDADO</span><p>'+esc(e.dont)+'</p></div></div></div>';updateSavedUI()}all('[data-custom]').forEach(b=>b.addEventListener('click',()=>setCustom(b.dataset.custom)));setCustom('casa');
function setTaste(id){const e=byId.get(id),target=query('#taste-stage');if(!e||!target)return;all('[data-taste]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.taste===id)));target.innerHTML='<div class="taste-stage-inner">'+(e.image?'<img src="assets/'+e.image+'.webp" alt="'+esc(e.imageAlt||e.title)+'">':'<span class="taste-stage-glyph" aria-hidden="true">'+e.kana+'</span>')+'<p class="eyebrow">'+esc(e.tag)+'</p><h3>'+esc(e.title)+'</h3>'+e.body.map(t=>'<p>'+esc(t)+'</p>').join('')+'<div class="stage-actions"><button class="button solid" data-entry="'+id+'">Descubra mais ↗</button><button class="stage-save" data-save="'+id+'">＋ Guardar no caderno</button></div></div>';updateSavedUI()}all('[data-taste]').forEach(b=>b.addEventListener('click',()=>setTaste(b.dataset.taste)));setTaste('ramen');
all('[data-person-filter]').forEach(b=>b.addEventListener('click',()=>{all('[data-person-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});all('.people-collection .entry-card').forEach(card=>card.hidden=b.dataset.personFilter!=='all'&&card.dataset.field!==b.dataset.personFilter)}));
function filterCollection(){const input=query('#collection-search');if(!input)return;const term=norm(input.value).trim(),genre=query('#collection-filter').value;let count=0;all('.anime-collection .entry-card').forEach(card=>{const e=byId.get(card.id);const match=(genre==='all'||e.genre===genre)&&norm([e.title,e.creator,e.lead,e.genre].join(' ')).includes(term);card.hidden=!match;if(match)count++});query('#collection-count').textContent=count+(count===1?' obra':' obras');query('#collection-empty').hidden=count!==0}query('#collection-search')?.addEventListener('input',filterCollection);query('#collection-filter')?.addEventListener('change',filterCollection);
const cities=entries.filter(e=>e.category==='cidades');const compareA=query('#compare-a'),compareB=query('#compare-b');function renderComparison(){if(!compareA||!compareB)return;query('#city-comparison').innerHTML='<div class="compare-cards">'+[compareA.value,compareB.value].map(id=>{const e=byId.get(id);return '<article class="compare-card"><img src="assets/'+e.image+'.webp" alt="Fotografia de '+esc(e.title)+'"><p class="eyebrow">'+esc(e.tag)+'</p><h3>'+esc(e.title)+'</h3><p>'+esc(e.body[0])+'</p><p>'+esc(e.body[1])+'</p><button data-entry="'+e.id+'">Veja o contexto e os créditos ↗</button></article>'}).join('')+'</div>'}if(compareA&&compareB){[compareA,compareB].forEach(select=>{select.innerHTML=cities.map(e=>'<option value="'+e.id+'">'+e.title+'</option>').join('');select.addEventListener('change',()=>{if(compareA.value===compareB.value){const other=select===compareA?compareB:compareA;other.value=cities.find(e=>e.id!==select.value).id}renderComparison()})});compareA.value='tokyo';compareB.value='naha';renderComparison()}
// The tanzaku is a local note. Never sent or shared automatically.
const wishForm=query('#wish-form'),wishInput=query('#wish-input');if(wishInput){wishInput.value=wish();if(wish())query('#wish-preview').textContent=wish();query('#wish-counter').textContent=wishInput.value.length+' / 140';wishInput.addEventListener('input',()=>{query('#wish-counter').textContent=wishInput.value.length+' / 140'});wishForm.addEventListener('submit',e=>{e.preventDefault();const text=wishInput.value.trim();if(!text){wishInput.focus();return}try{localStorage.setItem('yugen-wish-v1',text);query('#wish-preview').textContent=text;query('#wish-status').textContent='Seu desejo foi pendurado e guardado no caderno.';notify('Seu desejo está no caderno.')}catch{query('#wish-status').textContent='Não foi possível guardar o texto neste navegador.'}})}
const landscapeButton=query('[data-open-landscape]');if(landscapeButton){const landscape=document.createElement('dialog');landscape.className='landscape-dialog';landscape.setAttribute('aria-labelledby','landscape-title');landscape.innerHTML='<button class="close-dialog" aria-label="Fechar janela da floresta">✕</button><img src="assets/forest-moss.webp" alt="Fotografia real da floresta de Shiratani Unsuikyō, em Yakushima"><div class="landscape-focus-copy"><p class="eyebrow">YAKUSHIMA / UMA PAUSA, NO SEU RITMO</p><h2 id="landscape-title">Nem tudo precisa<br>acontecer <em>depressa.</em></h2><p>Observe uma raiz, uma textura, um ponto de luz.<br>Não há contagem regressiva. Fique o tempo que quiser.</p></div><a class="photo-caption" href="creditos.html#forest-moss">Foto real · Σ64 · CC BY 3.0 · Créditos ↗</a>';document.body.append(landscape);landscapeButton.addEventListener('click',()=>{landscape.showModal();syncLocks()});query('.close-dialog',landscape).addEventListener('click',()=>landscape.close());landscape.addEventListener('close',()=>{syncLocks();landscapeButton.focus()})}
function cardHTML(e,i){return '<article class="entry-card entry-'+e.category+' tone-'+(e.color||'paper')+'"><button class="entry-open" data-entry="'+e.id+'" aria-label="Ler: '+esc(e.title)+'"><div class="entry-art">'+(e.image?'<img src="assets/'+e.image+'.webp" loading="lazy" alt="'+esc(e.imageAlt||e.title)+'">':'<span class="entry-glyph" aria-hidden="true">'+esc(e.kana)+'</span>')+'<span class="entry-index">'+String(i+1).padStart(2,'0')+'</span><span class="entry-arrow" aria-hidden="true">↗</span></div><div class="entry-copy"><span class="entry-tag">'+esc(categories[e.category].name.toUpperCase())+'</span><h3>'+esc(e.title)+'</h3><p>'+esc(e.lead)+'</p><span class="entry-read">Retome essa descoberta ↗</span></div></button><button class="entry-save" data-save="'+e.id+'" aria-label="Retirar '+esc(e.title)+' do caderno" aria-pressed="true">✓</button></article>'}
function renderNotebook(){const target=query('#notebook-items');if(!target)return;const ids=saved();target.innerHTML=ids.map((id,i)=>cardHTML(byId.get(id),i)).join('');query('#notebook-empty').hidden=ids.length>0;query('#notebook-summary').textContent=ids.length+(ids.length===1?' descoberta guardada.':' descobertas guardadas.');const text=wish();query('#notebook-wish').hidden=!text;query('#notebook-wish>p:not(.eyebrow)').textContent=text;updateSavedUI()}
query('#remove-wish')?.addEventListener('click',()=>{try{localStorage.removeItem('yugen-wish-v1')}catch{}renderNotebook();notify('Desejo retirado do caderno.')});query('#export-notebook')?.addEventListener('click',()=>{let text='YŪGEN — MEU CADERNO\nJapão além do óbvio\n\n';saved().forEach(id=>{const e=byId.get(id);text+=e.title+'\n'+e.lead+'\n'+new URL(href(e),location.href).href+'\n\n'});if(wish())text+='MEU TANZAKU\n'+wish()+'\n';const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='meu-caderno-yugen.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Seu caderno foi preparado para download.')});renderNotebook();updateSavedUI();addEventListener('storage',()=>{renderNotebook();updateSavedUI()});
const readId=new URLSearchParams(location.search).get('ler');if(readId&&byId.has(readId))openReader(readId);
})();
